import { AbsoluteFill, Audio, Img, staticFile, useCurrentFrame } from "remotion";
import { fg, setInv, Stamp, ArtImg, ART_R, BLUE, Checker, Col, Cursor, INK, INTER, io, k, Key, lin, Logo, mix, pathAt, PhotoImg, Pill, pop, SAIRA, TBox, Toolbar, WA, WHITE, Words } from "./Kit5";
import { B1, B2, B3, B4, B5, Enter, S1, S2, S3, S4, S5, Sweep, V } from "./Kadinho7a";

// Kadocria v4 — cenas 6 a 10 e a montagem (mesma voz e mesmo som da v3). Mais animação que foto (pedido do cliente), estética Photoshop.
export const K8_FPS = 30;
export const K8_DUR = 46.0;
export const K8_FRAMES = Math.round(K8_DUR * K8_FPS);

const B6 = V(25.99) - 0.15; // "Os quadros já fazem sucesso…"
const B7 = V(33.09) - 0.15; // "Quadros a partir de…"
const B8 = V(38.41) - 0.15; // "Uma forma de eternizar…"
const B9 = V(45.11) - 0.15; // "Peça o seu…"

// v5: viradas do fundo escuro ↔ claro, na palavra forte de cada cena e na troca de cena (fecha no escuro, com o logo branco)
setInv([
  V(5.16) - 0.05, // "obra de arte" → claro
  B2, // Kadocria → escuro
  V(9.14) - 0.1, // "em quadros" → claro
  B3, // como funciona → escuro
  V(14.78) - 0.1, // "o quadro fica pronto" → claro
  B4, // "porque cada arte" → escuro
  V(19.96) - 0.04, // "uma história" → claro
  B5, // canvas → escuro
  V(23.15) - 0.1, // "com moldura" → claro (segue claro no "sucesso")
  V(29.19) - 0.12, // "atletas profissionais" → escuro
  V(34.11) - 0.05, // preço → claro
  B8, // "eternizar" → escuro
  V(42.29) - 0.12, // "presente" → claro
  B9, // quadro final → escuro
]);

// ───────── 6 · canvas 100% algodão (lupa mostra a trama) e moldura flutuante preta ou branca ─────────
const S6: React.FC<{ t: number }> = ({ t }) => {
  const a = B5;
  const M = V(23.15) - 0.1;
  const P = V(24.31) - 0.05;
  const Br = V(25.03) - 0.05;
  const w = 440;
  const h = w * ART_R;
  const L = 540 - w / 2;
  const T = 480;
  const draw = lin(t, M + 0.05, M + 0.6);
  const white = io(t, Br, 0.3);
  const gap = 24;
  const fw = 22;
  const per = 2 * (w + 2 * gap + fw + h + 2 * gap + fw);
  const frameC = `rgb(${Math.round(mix(20, 250, white))},${Math.round(mix(20, 250, white))},${Math.round(mix(20, 248, white))})`;
  // lupa passeia pela tela
  const lens: Key[] = [[a, 900, 1000], [a + 0.4, 640, 700], [V(21.73), 470, 640], [V(22.35), 620, 860], [M, 650, 900]];
  const [lx, ly] = pathAt(lens, t);
  const showLens = t < M;
  const keys: Key[] = [[M, 650, 900], [M + 0.05, L - gap - fw, T - gap - fw], [M + 0.6, L + w + gap + fw, T + h + gap + fw], [P - 0.2, 760, 1330], [P, 330, 1360], [Br, 700, 1360]];
  const [cx, cy] = pathAt(keys, t);
  return (
    <>
      <Checker t={t} tag="06 · acabamento" />
      <Toolbar t={t} active={t < M ? "zoom" : "marquee"} flash={t < M ? a + 0.1 : M} />
      <div style={{ position: "absolute", left: L, top: T, transform: `translateY(${(-lin(t, M + 0.4, M + 0.9) * 10).toFixed(1)}px)` }}>
        <ArtImg n={9} w={w} style={{ boxShadow: `0 ${mix(20, 40, draw).toFixed(0)}px ${mix(40, 70, draw).toFixed(0)}px rgba(0,0,0,0.3)` }} />
      </div>
      {/* moldura desenhada em volta, com folga (flutuante) */}
      <svg width={w + 2 * (gap + fw) + 10} height={h + 2 * (gap + fw) + 10} style={{ position: "absolute", left: L - gap - fw - 5, top: T - gap - fw - 5, overflow: "visible" }}>
        <rect x={5 + fw / 2} y={5 + fw / 2} width={w + 2 * gap + fw} height={h + 2 * gap + fw} fill="none" stroke={frameC} strokeWidth={fw} strokeDasharray={per} strokeDashoffset={per * (1 - draw)} />
        {white > 0.5 ? <rect x={5} y={5} width={w + 2 * (gap + fw)} height={h + 2 * (gap + fw)} fill="none" stroke="#C8C8C8" strokeWidth={2} /> : null}
      </svg>
      {showLens ? (
        <div style={{ position: "absolute", left: lx - 120, top: ly - 120, width: 240, height: 240, borderRadius: 120, border: `8px solid ${INK}`, overflow: "hidden", background: "#EFEDE6", boxShadow: "0 18px 40px rgba(0,0,0,0.3)", transform: `scale(${pop(t, a + 0.3, 0.4).toFixed(3)})` }}>
          <div style={{ position: "absolute", inset: 0, background: "repeating-linear-gradient(0deg, rgba(120,110,95,0.28) 0 6px, rgba(255,255,255,0) 6px 12px), repeating-linear-gradient(90deg, rgba(120,110,95,0.22) 0 6px, rgba(255,255,255,0) 6px 12px)" }} />
          <div style={{ position: "absolute", left: 120 + 84, top: 120 + 84, width: 70, height: 16, borderRadius: 8, background: INK, transform: "rotate(45deg)", transformOrigin: "0 50%" }} />
        </div>
      ) : null}
      <Col top={1150} gap={8}>
        {t < M ? (
          <>
            <Words t={t} font="small" size={46} words={[["canvas", V(21.29)]]} />
            <Words t={t} size={112} words={[["100%", V(21.73), BLUE]]} />
            <Words t={t} size={112} words={[["algodão", V(22.35)]]} />
          </>
        ) : (
          <>
            <Words t={t} font="small" size={46} words={[["com", V(23.15)], ["moldura", V(23.29)]]} />
            <Words t={t} size={112} words={[["flutuante", V(23.63), BLUE]]} />
          </>
        )}
      </Col>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1330, display: "flex", justifyContent: "center", gap: 26 }}>
        {[
          { at: P, label: "preta", on: t >= P && t < Br, bg: INK, fg: WHITE },
          { at: P, label: "branca", on: t >= Br, bg: WHITE, fg: INK },
        ].map((c) => (
          <div key={c.label} style={{ fontFamily: SAIRA, fontWeight: 700, fontSize: 48, textTransform: "uppercase", padding: "14px 44px 18px", borderRadius: 999, border: `4px solid ${fg(t)}`, background: c.on ? c.bg : "transparent", color: c.on ? c.fg : fg(t), opacity: t >= c.at ? (c.on ? 1 : 0.35) : 0, boxShadow: c.on ? "0 14px 30px rgba(0,0,0,0.2)" : undefined, transform: `scale(${(t >= c.at ? 1 + (1 - k(t, c.on && c.label === "branca" ? Br : c.at, 0.25)) * 0.18 : 0.8).toFixed(3)})` }}>
            {c.label}
          </div>
        ))}
      </div>
      {t >= M ? <Cursor t={t} x={cx} y={cy} clicks={[M + 0.05, P, Br]} /> : null}
    </>
  );
};

// ───────── 7 · sucesso no beach tennis; atletas profissionais encomendaram e receberam ─────────
const Racket: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s * 1.25} viewBox="0 0 80 100">
    <rect x={10} y={4} width={60} height={64} rx={30} fill={INK} />
    {[0, 1, 2, 3, 4].map((r) => [0, 1, 2, 3].map((c) => <circle key={`${r}${c}`} cx={22 + c * 12 + (r % 2) * 6 - 3} cy={18 + r * 10} r={2.6} fill={WHITE} opacity={0.85} />))}
    <rect x={33} y={64} width={14} height={32} rx={5} fill={INK} />
    <rect x={33} y={74} width={14} height={4} fill={BLUE} />
    <rect x={33} y={82} width={14} height={4} fill={BLUE} />
  </svg>
);
const S7: React.FC<{ t: number }> = ({ t }) => {
  const a = B6;
  const W2 = V(27.59) - 0.08; // "no mundo do beach tennis"
  const A = V(29.19) - 0.12; // "atletas profissionais"
  const E = V(30.23) - 0.08; // "já encomendaram e receberam"
  const R = V(31.29);
  if (t < A) {
    const hop = Math.abs(Math.sin((t - a) * 4.2));
    const sw = Math.sin((t - a) * 4.2) * 10;
    return (
      <>
        <Checker t={t} tag="07 · quem já tem" />
        <Toolbar t={t} active="move" />
        <div style={{ position: "absolute", left: 540 - 150, top: 500, transform: `rotate(${(-18 + sw).toFixed(1)}deg) scale(${pop(t, a + 0.05, 0.5).toFixed(3)})`, transformOrigin: "50% 80%" }}>
          <Racket s={300} />
        </div>
        <div style={{ position: "absolute", left: 720, top: 550 + (1 - hop) * 260, width: 74, height: 74, borderRadius: 37, background: "#E8F04A", border: `4px solid ${INK}`, transform: `scale(${pop(t, a + 0.2, 0.4).toFixed(3)})` }} />
        <div style={{ position: "absolute", left: 0, right: 0, top: 960, display: "flex", justifyContent: "center", gap: 14 }}>
          {[0, 1, 2, 3, 4].map((i) => (
            <svg key={i} width={70} height={70} viewBox="0 0 24 24" style={{ transform: `scale(${pop(t, V(26.97) + i * 0.08, 0.35).toFixed(3)})` }}>
              <path d="M12 2l3 6.5 7 .8-5.2 4.8 1.4 7L12 17.6 5.8 21l1.4-7L2 9.3l7-.8z" fill={BLUE} />
            </svg>
          ))}
        </div>
        <Col top={1150} gap={8}>
          {t < W2 ? (
            <>
              <Words t={t} font="small" size={46} words={[["os", V(25.99)], ["quadros", V(26.13)], ["já", V(26.51)], ["fazem", V(26.65)]]} />
              <Words t={t} size={120} words={[["sucesso", V(26.97), BLUE]]} />
            </>
          ) : (
            <>
              <Words t={t} font="small" size={46} words={[["no", V(27.59)], ["mundo", V(27.71)], ["do", V(27.89)]]} />
              <Words t={t} size={104} words={[["beach", V(27.99)], ["tennis", V(28.21), BLUE]]} />
            </>
          )}
        </Col>
      </>
    );
  }
  // v8: a foto da entrega (Kadinho com o atleta e o quadro da abertura) sai do documento e abre inteira na tela;
  // depois encolhe de volta para a polaroide do meio, as outras duas entram e o selo bate.
  const RS = V(30.23) + 0.38; // começa a voltar
  const grow = io(t, A, 0.55);
  const back = io(t, RS, 0.55);
  const full = grow * (1 - back);
  const P2 = { x: 540 - 158 + 14, y: 520 + 14, w: 288, h: 380 }; // foto dentro da polaroide do meio
  const FW = 1080;
  const FH = 1350;
  const F = { x: 0, y: 440, w: FW, h: FH };
  const s0 = back > 0 ? P2 : { x: 540 - 220, y: 520, w: 440, h: 550 }; // entrada: sai do meio do documento
  const r = { x: mix(s0.x, F.x, full), y: mix(s0.y, F.y, full), w: mix(s0.w, F.w, full), h: mix(s0.h, F.h, full) };
  const push = 1 + lin(t, A + 0.55, RS) * 0.03;
  const border = 14 * back;
  const SIDE = [
    { n: 6, x: -235, r: -6, at: RS + 0.3 },
    { n: 10, x: 235, r: 6, at: RS + 0.45 },
  ];
  return (
    <>
      <Checker t={t} tag="07 · quem já tem" />
      <Toolbar t={t} active="move" flash={RS + 0.55} />
      {SIDE.map((p) => {
        const e = pop(t, p.at, 0.5);
        return t < p.at ? null : (
          <div key={p.n} style={{ position: "absolute", left: 540 - 158 + p.x, top: 520 + (1 - e) * 900, transform: `rotate(${p.r}deg)` }}>
            <div style={{ background: WHITE, padding: "14px 14px 54px", boxShadow: "0 24px 50px rgba(0,0,0,0.25)" }}>
              <PhotoImg n={p.n} w={288} h={380} fy={0.4} style={{ boxShadow: "none" }} />
            </div>
          </div>
        );
      })}
      {/* fundo da foto aberta: a própria foto ampliada e desfocada, escurecida de leve */}
      {full > 0.001 ? (
        <div style={{ position: "absolute", inset: 0, opacity: full, overflow: "hidden" }}>
          <Img src={staticFile("kadinho/e1.jpg")} style={{ position: "absolute", left: -120, top: -120, width: 1320, height: 2160, objectFit: "cover", filter: "blur(40px)", transform: `scale(${push.toFixed(4)})` }} />
          <div style={{ position: "absolute", inset: 0, background: "rgba(10,10,12,0.35)" }} />
        </div>
      ) : null}
      {/* a foto: inteira enquanto aberta, vira polaroide ao voltar */}
      {(
        <div style={{ position: "absolute", left: r.x - border, top: r.y - border, padding: `${border}px ${border}px ${(54 * back).toFixed(1)}px`, background: back > 0 ? WHITE : "transparent", boxShadow: `0 ${mix(24, 40, full).toFixed(0)}px ${mix(50, 80, full).toFixed(0)}px rgba(0,0,0,${mix(0.25, 0.45, full).toFixed(2)})`, transform: `scale(${(grow < 1 ? 0.92 + 0.08 * grow : 1).toFixed(4)})`, transformOrigin: "50% 50%", opacity: Math.min(1, grow * 3) }}>
          <div style={{ width: r.w, height: r.h, overflow: "hidden", position: "relative", background: INK }}>
            <Img src={staticFile("kadinho/e1.jpg")} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", objectPosition: "50% 40%", transform: `scale(${(full > 0 ? push : 1).toFixed(4)})` }} />
          </div>
        </div>
      )}
      <Stamp t={t} at={Math.max(R, RS + 0.65)} label="entregues" x={540} y={760} />
      {/* legenda: no alto enquanto a foto está aberta; embaixo, no estilo de sempre, depois que volta */}
      {full > 0.6 ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: 0, opacity: Math.max(0, Math.min(1, (full - 0.6) / 0.35)), textShadow: "0 4px 18px rgba(0,0,0,0.55)" }}>
          <Col top={262} gap={4}>
            {t < E ? (
              <>
                <Words t={t} size={76} color={WHITE} words={[["atletas", V(29.19)]]} />
                <Words t={t} size={76} words={[["profissionais", V(29.61), BLUE]]} />
              </>
            ) : (
              <>
                <Words t={t} font="small" size={44} color={WHITE} words={[["já", V(30.23)], ["encomendaram", V(30.35)]]} />
              </>
            )}
          </Col>
        </div>
      ) : null}
      {t >= RS ? (
        <div style={{ position: "absolute", inset: 0, opacity: k(t, RS + 0.45, 0.25) }}>
          <Col top={1150} gap={8}>
            <Words t={t} font="small" size={46} words={[["já", V(30.23)], ["encomendaram", V(30.35)]]} />
            <Words t={t} size={104} words={[["e", V(31.21)], ["receberam", V(31.29), BLUE]]} />
            <Words t={t} font="small" size={46} words={[["os", V(31.79)], ["seus", V(31.93)]]} />
          </Col>
        </div>
      ) : null}
    </>
  );
};

// ───────── 8 · oferta: preço numa caixa de transformação, PIX e 3x ─────────
const S8: React.FC<{ t: number }> = ({ t }) => {
  const a = B7;
  const N = V(34.11) - 0.05;
  const X = V(35.33) - 0.05;
  const C3 = V(36.29) - 0.05;
  const e = k(t, N, 0.22);
  const keys: Key[] = [[a, 880, 1080], [N, 820, 1100], [X - 0.25, 400, 1250], [X, 380, 1240], [C3 - 0.25, 700, 1250], [C3, 690, 1240], [B8, 760, 1300]];
  const [cx, cy] = pathAt(keys, t);
  return (
    <>
      <Checker t={t} tag="08 · investimento" />
      <Toolbar t={t} active="text" flash={N} />
      {[4, 7, 15].map((n, i) => {
        const p = pop(t, a + 0.08 + i * 0.1, 0.45);
        return (
          <div key={n} style={{ position: "absolute", left: 540 - 105 + (i - 1) * 245, top: 480 + (1 - p) * 700, transform: `rotate(${((i - 1) * 5).toFixed(1)}deg) scale(${(1 + lin(t, a, B8) * 0.05).toFixed(4)})` }}>
            <div style={{ padding: 12, background: i === 1 ? INK : WHITE, boxShadow: "0 20px 40px rgba(0,0,0,0.22)" }}>
              <ArtImg n={n} w={186} style={{ boxShadow: "none" }} />
            </div>
          </div>
        );
      })}
      <Col top={800} gap={0}>
        <Words t={t} font="small" size={46} color="#4A4A4A" words={[["quadros", V(33.09)], ["a", V(33.51)], ["partir", V(33.59)], ["de", V(33.89)]]} />
      </Col>
      <div style={{ position: "absolute", left: 0, right: 0, top: 870, textAlign: "center", fontFamily: SAIRA, fontWeight: 800, fontSize: 230, lineHeight: 1, color: INK, opacity: Math.min(1, e * 4), transform: `scale(${(1.7 - 0.7 * e).toFixed(4)})`, whiteSpace: "nowrap" }}>
        <span style={{ fontSize: 100, verticalAlign: "0.95em", marginRight: 14, color: BLUE }}>R$</span>{Math.round(lin(t, N, N + 0.45) * 500)}
      </div>
      {t > N + 0.1 && t < N + 1.1 ? <TBox x={250} y={870} w={580} h={240} o={1 - k(t, N + 0.8, 0.3)} /> : null}
      <div style={{ position: "absolute", left: 0, right: 0, top: 1190, display: "flex", justifyContent: "center", gap: 22 }}>
        <div style={{ opacity: t >= X ? 1 : 0, transform: `scale(${(t >= X ? 1 + (1 - k(t, X, 0.25)) * 0.2 : 0.8).toFixed(3)})` }}>
          <Pill size={46} bg={WHITE} fg={INK}>
            <svg width={40} height={40} viewBox="0 0 24 24"><path d="M12 2l10 10-10 10L2 12z" fill="none" stroke={WA} strokeWidth={3} /></svg>
            PIX
          </Pill>
        </div>
        <div style={{ opacity: t >= C3 ? 1 : 0, transform: `scale(${(t >= C3 ? 1 + (1 - k(t, C3, 0.25)) * 0.2 : 0.8).toFixed(3)})` }}>
          <Pill size={46} bg={BLUE}>
            <svg width={44} height={44} viewBox="0 0 24 24" fill="none" stroke={WHITE} strokeWidth={2}><rect x={2} y={5} width={20} height={14} rx={2} /><path d="M2 10h20" /></svg>
            até 3x no cartão
          </Pill>
        </div>
      </div>
      <Cursor t={t} x={cx} y={cy} clicks={[X, C3]} />
    </>
  );
};

// ───────── 9 · eternizar conquistas (troféu) e momentos (coração); presente (caixa que abre e revela o quadro) ─────────
const Trophy: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={INK} strokeWidth={1.6} strokeLinecap="round" strokeLinejoin="round">
    <path d="M7 3h10v6a5 5 0 0 1-10 0z" fill={BLUE} />
    <path d="M7 5H4v2a3 3 0 0 0 3 3M17 5h3v2a3 3 0 0 1-3 3M12 14v4M8 21h8M9 18h6v3H9z" />
  </svg>
);
const Heart: React.FC<{ s: number; beat: number }> = ({ s, beat }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" style={{ transform: `scale(${(1 + beat * 0.08).toFixed(3)})` }}>
    <path d="M12 21s-8-5-8-11a4.5 4.5 0 0 1 8-2.8A4.5 4.5 0 0 1 20 10c0 6-8 11-8 11z" fill="#FF4D6D" stroke={INK} strokeWidth={1.6} strokeLinejoin="round" />
  </svg>
);
const S9: React.FC<{ t: number }> = ({ t }) => {
  const a = B8;
  const G = V(42.29) - 0.12; // "um presente com significado"
  const away = io(t, G, 0.35);
  const open = io(t, V(42.37) + 0.35, 0.4);
  const rise = io(t, V(42.37) + 0.55, 0.6);
  return (
    <>
      <Checker t={t} tag="09 · presente" />
      <Toolbar t={t} active={t < G ? "brush" : "move"} flash={t < G ? V(39.41) : G} />
      {away < 1 ? (
        <>
          <div style={{ position: "absolute", left: 300 - 150, top: 520, transform: `scale(${(pop(t, V(39.41) - 0.05, 0.45) * (1 - away)).toFixed(3)}) rotate(${(Math.sin((t - a) * 2) * 3).toFixed(1)}deg)` }}>
            <Trophy s={300} />
          </div>
          <div style={{ position: "absolute", left: 780 - 150, top: 520, transform: `scale(${(pop(t, V(40.43) - 0.05, 0.45) * (1 - away)).toFixed(3)})` }}>
            <Heart s={300} beat={Math.max(0, Math.sin((t - a) * 7))} />
          </div>
        </>
      ) : null}
      {t >= G ? (
        <div style={{ position: "absolute", left: 540 - 200, top: 540, width: 400, height: 520, transform: `scale(${pop(t, G + 0.1, 0.45).toFixed(3)})`, transformOrigin: "50% 100%" }}>
          {/* quadro saindo da caixa */}
          <div style={{ position: "absolute", left: 200 - 140, top: 250 - rise * 300, padding: 10, background: INK, boxShadow: "0 20px 40px rgba(0,0,0,0.3)" }}>
            <ArtImg n={16} w={260} style={{ boxShadow: "none" }} />
          </div>
          <div style={{ position: "absolute", left: 0, top: 250, width: 400, height: 270, background: BLUE, borderRadius: 10, boxShadow: "0 24px 50px rgba(0,0,0,0.25)" }}>
            <div style={{ position: "absolute", left: 180, top: 0, width: 40, height: 270, background: WHITE }} />
          </div>
          <div style={{ position: "absolute", left: -20, top: 190, width: 440, height: 74, background: "#1676D8", borderRadius: 10, transform: `translate(${(open * 160).toFixed(1)}px, ${(-open * 200).toFixed(1)}px) rotate(${(open * 28).toFixed(1)}deg)`, boxShadow: "0 10px 20px rgba(0,0,0,0.2)" }}>
            <div style={{ position: "absolute", left: 200, top: 0, width: 40, height: 74, background: WHITE }} />
          </div>
        </div>
      ) : null}
      <Col top={1150} gap={8}>
        {t < G ? (
          <>
            <Words t={t} font="small" size={46} words={[["uma", V(38.41)], ["forma", V(38.61)], ["de", V(38.87)], ["eternizar", V(38.93)]]} />
            {t < V(40.35) - 0.06 ? (
              <Words t={t} size={112} words={[["conquistas", V(39.41), BLUE]]} />
            ) : (
              <>
