export const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const OUT = Easing.bezier(0.16, 1, 0.3, 1);
export const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
export const BACK = Easing.out(Easing.back(1.5));
export const k = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
export const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
export const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
export const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
export const mix = (a: number, b: number, p: number) => a + (b - a) * p;
export const clamp = (x: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, x));

// v5: inversão de fundo (pedido do cliente: mais dinamismo). Nos tempos de INV a área de trabalho vira de escura para
// clara (e volta) num círculo que abre do centro; o texto de fora do documento troca de claro para escuro junto.
let INV: number[] = [];
export const setInv = (l: number[]) => {
  INV = [...l].sort((a, b) => a - b);
};
const FLIP = 0.3;
// estado do fundo: light = claro depois da última virada; p = progresso da virada
export const invAt = (t: number) => {
  const done = INV.filter((a) => t >= a);
  const last = done.length ? done[done.length - 1] : -10;
  return { light: done.length % 2 === 1, p: io(t, last, FLIP) };
};
// cor do texto que fica sobre a área de trabalho (troca no meio da virada)
export const fg = (t: number, dark = TXT, light = INK) => {
  const { light: l, p } = invAt(t);
  return (p > 0.5 ? l : !l) ? light : dark;
};
