    <div style={{ position: "absolute", inset: 0, backgroundImage: `radial-gradient(${light ? "rgba(0,0,0,0.09)" : "rgba(255,255,255,0.07)"} 1.5px, transparent 1.6px)`, backgroundSize: "36px 36px", backgroundPosition: `${(t * 6).toFixed(1)}px ${(t * 4).toFixed(1)}px` }} />
