// centro de cada ícone na barra (para o cursor ir até ele)
export const toolX = (n: string) => 140 + 18 + 35 + TOOLS.indexOf(n) * ((800 - 36 - 70) / (TOOLS.length - 1));
export const TOOL_Y = 308;

// cursor: seta, mira de pincel ou cursor de texto, em caminho de pontos [tempo, x, y]
export type Key = [number, number, number];
export const pathAt = (keys: Key[], t: number): [number, number] => {
  if (t <= keys[0][0]) return [keys[0][1], keys[0][2]];
  for (let i = 1; i < keys.length; i++) {
    const [b, bx, by] = keys[i];
    const [a, ax, ay] = keys[i - 1];
    if (t <= b) {
      const p = IN_OUT((t - a) / Math.max(1e-6, b - a));
      return [mix(ax, bx, p), mix(ay, by, p)];
    }
  }
  const l = keys[keys.length - 1];
  return [l[1], l[2]];
};
export const Cursor: React.FC<{ t: number; x: number; y: number; kind?: "arrow" | "brush" | "ibeam"; clicks?: number[]; size?: number }> = ({ t, x, y, kind = "arrow", clicks = [], size = 1 }) => {
  const c = clicks.find((a) => t >= a && t < a + 0.4);
  const press = c !== undefined ? 1 - 0.14 * Math.sin(Math.PI * clamp((t - c) / 0.18, 0, 1)) : 1;
  return (
    <div style={{ position: "absolute", left: x, top: y, width: 0, height: 0, zIndex: 50 }}>
      {c !== undefined ? <div style={{ position: "absolute", left: -40, top: -40, width: 80, height: 80, borderRadius: 40, border: `5px solid ${BLUE}`, transform: `scale(${(0.3 + k(t, c, 0.4) * 1.1).toFixed(3)})`, opacity: 1 - lin(t, c, c + 0.4) }} /> : null}
      <div style={{ transform: `scale(${(press * size).toFixed(3)})`, transformOrigin: "0 0" }}>
        {kind === "arrow" ? (
          <svg width={64} height={64} viewBox="0 0 24 24" style={{ position: "absolute", left: -6, top: -4, filter: "drop-shadow(0 4px 6px rgba(0,0,0,0.35))" }}>
            <path d="M5 2l14 12h-7l4 7-3 1-4-7-4 5z" fill={WHITE} stroke={INK} strokeWidth={1.4} strokeLinejoin="round" />
          </svg>
        ) : kind === "brush" ? (
          <div style={{ position: "absolute", left: -60, top: -60, width: 120, height: 120, borderRadius: 60, border: `3px solid ${WHITE}`, boxShadow: `0 0 0 2px ${INK}` }} />
        ) : (
          <svg width={40} height={70} viewBox="0 0 12 22" style={{ position: "absolute", left: -20, top: -35 }}>
            <path d="M3 1h6M6 1v20M3 21h6" stroke={INK} strokeWidth={1.8} fill="none" />
          </svg>
        )}
      </div>
    </div>
  );
};

// seleção tracejada ("formigas") em volta de um retângulo
export const Ants: React.FC<{ t: number; x: number; y: number; w: number; h: number; o?: number; r?: number }> = ({ t, x, y, w, h, o = 1, r = 0 }) => (
  <svg width={w + 8} height={h + 8} style={{ position: "absolute", left: x - 4, top: y - 4, opacity: o, overflow: "visible" }}>
