);
// caixa de transformação (Ctrl+T): moldura azul fina com 8 alças
export const TBox: React.FC<{ x: number; y: number; w: number; h: number; o?: number }> = ({ x, y, w, h, o = 1 }) => {
  const hs = 22;
  const pts = [[0, 0], [0.5, 0], [1, 0], [0, 0.5], [1, 0.5], [0, 1], [0.5, 1], [1, 1]];
  return (
    <div style={{ position: "absolute", left: x, top: y, width: w, height: h, border: `3px solid ${BLUE}`, opacity: o, boxSizing: "border-box" }}>
      {pts.map(([px, py], i) => (
        <div key={i} style={{ position: "absolute", left: px * w - hs / 2 - 1.5, top: py * h - hs / 2 - 1.5, width: hs, height: hs, background: WHITE, border: `3px solid ${BLUE}`, boxSizing: "border-box" }} />
      ))}
    </div>
  );
};

// texto palavra por palavra no tempo da voz. Linha pequena: as palavras já estão lá, apagadas, e acendem quando ditas
// (como a legenda das referências). Linha grande: cada palavra entra com borrão de movimento e estica-e-volta. Depois fica parado.
export type Wd = [string, number, string?];
export const Words: React.FC<{ t: number; words: Wd[]; size: number; color?: string; font?: "big" | "small"; gap?: number }> = ({ t, words, size, color, font = "big", gap }) => {
  const base = color ?? (font === "big" ? fg(t) : fg(t, "#D8D8D8", "#2E2E2E"));
  return (
    <div style={{ display: "flex", justifyContent: "center", alignItems: "baseline", gap: gap ?? size * 0.26, whiteSpace: "nowrap", ...(font === "big" ? { fontFamily: SAIRA, fontWeight: 800, textTransform: "uppercase", letterSpacing: "-0.01em", lineHeight: 1.0 } : { fontFamily: INTER, fontWeight: 600, lineHeight: 1.2 }), fontSize: size, color: base }}>
      {words.map(([w, at, c], i) => {
        if (font === "small") {
          const on = k(t, at - 0.03, 0.15);
          return (
            <span key={i} style={{ display: "inline-block", color: c ?? base, opacity: 0.22 + 0.78 * on, transform: `translateY(${((1 - k(t, at - 0.03, 0.25)) * 4).toFixed(1)}px)` }}>{w}</span>
          );
        }
        const e = k(t, at - 0.05, 0.3);
        const blur = (1 - k(t, at - 0.05, 0.18)) * 14;
        const sx = 1 + (1 - e) * 0.35;
        const sy = 1 - (1 - e) * 0.25 + Math.sin(Math.min(1, e * 1.4) * Math.PI) * 0.06;
        return (
          <span key={i} style={{ display: "inline-block", opacity: k(t, at - 0.05, 0.06), transform: `translateX(${((1 - e) * -size * 0.5).toFixed(1)}px) scale(${sx.toFixed(3)}, ${sy.toFixed(3)})`, filter: blur > 0.3 ? `blur(${blur.toFixed(1)}px)` : undefined, color: c ?? base }}>{w}</span>
        );
      })}
    </div>
  );
};
// balão explicativo com linha até o ponto (como nas referências): ponto azul, linha que se desenha e etiqueta escura
export const Callout: React.FC<{ t: number; at: number; px: number; py: number; lx: number; ly: number; label: string; sub?: string }> = ({ t, at, px, py, lx, ly, label, sub }) => {
  const d = k(t, at, 0.3);
  const b = k(t, at + 0.2, 0.3);
  if (t < at) return null;
  return (
    <>
      <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0, overflow: "visible", pointerEvents: "none" }}>
        <line x1={px} y1={py} x2={mix(px, lx, d)} y2={mix(py, ly, d)} stroke={BLUE} strokeWidth={3} />
        <circle cx={px} cy={py} r={9 * pop(t, at, 0.3)} fill={BLUE} stroke={WHITE} strokeWidth={3} />
      </svg>
      <div style={{ position: "absolute", left: lx, top: ly, transform: `translate(${lx > px ? "0" : "-100%"}, -50%) scale(${(0.85 + 0.15 * b).toFixed(3)})`, transformOrigin: lx > px ? "0 50%" : "100% 50%", opacity: b, background: "rgba(22,22,24,0.92)", border: `2px solid ${BLUE}`, borderRadius: 12, padding: "10px 18px 12px", whiteSpace: "nowrap" }}>
        <div style={{ fontFamily: INTER, fontWeight: 700, fontSize: 30, color: TXT }}>{label}</div>
        {sub ? <div style={{ fontFamily: MONO, fontWeight: 500, fontSize: 20, color: "#9FC9FF", textTransform: "uppercase", marginTop: 2 }}>{sub}</div> : null}
      </div>
    </>
  );
};
// selo inclinado que bate (como o "DE PROPÓSITO" da referência)
export const Stamp: React.FC<{ t: number; at: number; label: string; x: number; y: number; rot?: number }> = ({ t, at, label, x, y, rot = -8 }) => {
  if (t < at) return null;
  const e = k(t, at, 0.22);
  return (
    <div style={{ position: "absolute", left: x, top: y, transform: `translate(-50%, -50%) rotate(${rot}deg) scale(${(2 - e).toFixed(3)})`, opacity: Math.min(1, e * 3), padding: "12px 34px 16px", border: `6px solid ${BLUE}`, borderRadius: 14, background: "rgba(255,255,255,0.94)", color: BLUE, fontFamily: SAIRA, fontWeight: 800, fontSize: 64, textTransform: "uppercase", letterSpacing: "0.02em", boxShadow: "0 18px 40px rgba(0,0,0,0.35)", whiteSpace: "nowrap" }}>{label}</div>
  );
};
export const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ top, gap = 0, children, style }) => (
  <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap, ...style }}>{children}</div>
);

// camadas: arte final e foto de entrega como "documento" sobre o quadriculado
export const ART_R = 1600 / 1210;
export const ArtImg: React.FC<{ n: number; w: number; style?: React.CSSProperties }> = ({ n, w, style }) => (
  <Img src={staticFile(`kadinho/a${n}.jpg`)} style={{ width: w, height: w * ART_R, display: "block", boxShadow: "0 30px 60px rgba(0,0,0,0.28), 0 6px 14px rgba(0,0,0,0.16)", ...style }} />
);
export const PhotoImg: React.FC<{ n: number; w: number; h: number; fy?: number; style?: React.CSSProperties }> = ({ n, w, h, fy = 0.45, style }) => (
