    <Img src={staticFile(`kadinho/e${n}.jpg`)} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", objectPosition: `50% ${(fy * 100).toFixed(0)}%` }} />
  </div>
);
export const Logo: React.FC<{ w: number; white?: boolean; style?: React.CSSProperties }> = ({ w, white, style }) => <Img src={staticFile(`kadinho/logo-${white ? "branco" : "preto"}.png`)} style={{ width: w, display: "block", ...style }} />;
// pílula de rótulo
export const Pill: React.FC<{ children: React.ReactNode; bg?: string; fg?: string; size?: number; style?: React.CSSProperties }> = ({ children, bg = INK, fg = WHITE, size = 46, style }) => (
  <div style={{ display: "flex", alignItems: "center", gap: 14, background: bg, color: fg, borderRadius: 999, padding: `${size * 0.36}px ${size * 0.8}px ${size * 0.42}px`, fontFamily: SAIRA, fontWeight: 700, fontSize: size, textTransform: "uppercase", whiteSpace: "nowrap", boxShadow: "0 14px 30px rgba(0,0,0,0.18)", ...style }}>{children}</div>
);

import { AbsoluteFill, Img, staticFile } from "remotion";
import { fg, MONO, Ants, ArtImg, Callout, INTER, SAIRA, ART_R, BLUE, Checker, Col, Cursor, Icon, INK, io, k, Key, lin, Logo, mix, MUTE, pathAt, PhotoImg, pop, TBox, Toolbar, TOOL_Y, toolX, UI, WHITE, Words } from "./Kit5";

// Kadocria v4 — cenas 1 a 5 (v3 refeita na pegada das referências do cliente: área de trabalho escura, etiquetas,
// balões explicativos, legenda que acende e palavras com borrão de movimento). Tempos: transcrição da voz v3 (edit/transcripts/voz-v3.json) convertida por V() para a
// voz com silêncios encurtados (audio/kadinho3-vo.wav, que entra em 0,15 s; cortes em (arquivo do cliente)).
const CUTS: [number, number][] = [[2.64, 0.88], [6.18, 0.25], [11.71, 0.18], [17.95, 0.2], [20.71, 0.33], [25.62, 0.12], [32.52, 0.32], [37.9, 0.26], [41.8, 0.24], [44.48, 0.38]];
export const V = (o: number) => o + 0.15 - CUTS.reduce((s, [a, r]) => (o > a ? s + r : s), 0);

export const B1 = V(3.77) - 0.12; // "Ela pode virar…"
export const B2 = V(6.68) - 0.15; // "A Kadocria…"
export const B3 = V(12.14) - 0.15; // "Você manda…"
export const B4 = V(18.4) - 0.15; // "Porque cada arte…"
export const B5 = V(21.29) - 0.15; // "Canvas…"

// entrada da cena: o palco desliza (direção alterna) e uma seleção azul varre o quadro
export const Enter: React.FC<{ t: number; at: number; dir: number; children: React.ReactNode }> = ({ t, at, dir, children }) => {
  // soco curto de zoom na troca (o quadriculado cobre a tela inteira o tempo todo)
  const p = k(t, at, 0.38);
  return <AbsoluteFill style={{ transform: `scale(${(1 + (1 - p) * 0.09).toFixed(4)}) rotate(${((1 - p) * 1.2 * dir).toFixed(3)}deg)` }}>{children}</AbsoluteFill>;
};
export const Sweep: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  if (t < at || t > at + 0.36) return null;
  const p = io(t, at, 0.36);
  const w = 1080 * Math.sin(Math.PI * p);
  return <div style={{ position: "absolute", left: 540 - w / 2, top: 400, width: w, height: 1080, background: "rgba(31,143,255,0.14)", border: `3px dashed ${BLUE}`, boxSizing: "border-box", zIndex: 40 }} />;
};

// ───────── 1 · gancho: a foto entra arrastada pelo cursor e é selecionada ─────────
const CARD = { x: 284, y: 470, w: 512, h: 640 };
export const S1: React.FC<{ t: number }> = ({ t }) => {
  const drag = io(t, 0.25, 0.6);
  const dx = (1 - drag) * 420;
  const dy = (1 - drag) * 760;
  const keys: Key[] = [[0, 1000, 1600], [0.25, CARD.x + CARD.w + dx + 420 - 420, CARD.y + CARD.h + 760 - 0], [0.85, CARD.x + CARD.w - 30, CARD.y + CARD.h - 30], [1.6, CARD.x + CARD.w + 60, CARD.y + CARD.h - 80], [2.55, toolX("brush"), TOOL_Y]];
  const [cx, cy] = t < 0.85 && t >= 0.25 ? [CARD.x + CARD.w - 30 + dx, CARD.y + CARD.h - 30 + dy] : pathAt(keys, t);
  return (
    <>
      <Checker t={t} z={mix(1.3, 1, k(t, 0, 0.6))} tag="01 · a foto" />
      <Toolbar t={t} active={t < 2.62 ? "move" : "brush"} flash={2.62} />
      <div style={{ position: "absolute", left: CARD.x + dx, top: CARD.y + dy, transform: `rotate(${((1 - drag) * 8).toFixed(2)}deg)` }}>
        <OrigImg />
      </div>
      <Ants t={t} x={CARD.x} y={CARD.y} w={CARD.w} h={CARD.h} o={k(t, 0.9, 0.2)} />
      <Col top={1150} gap={10}>
        <Words t={t} font="small" size={46} words={[["sabe", V(0.09)], ["aquela", V(0.25)], ["foto", V(0.65)], ["da", V(0.97)], ["sua", V(1.13)]]} />
        <Words t={t} size={112} words={[["maior", V(1.33)]]} />
        <Words t={t} size={112} words={[["conquista?", V(1.75), BLUE]]} />
      </Col>
      <Cursor t={t} x={cx} y={cy} clicks={[0.25, 2.62]} />
    </>
  );
};

// v7: a foto que abre é a do atleta no dia da conquista (original do projeto), não a foto da entrega
const OrigImg: React.FC = () => (
  <div style={{ width: CARD.w, height: CARD.h, overflow: "hidden", position: "relative", boxShadow: "0 30px 60px rgba(0,0,0,0.28)", background: INK }}>
    <Img src={staticFile("kadinho/o1.jpg")} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", objectPosition: "50% 40%" }} />
  </div>
);

// ───────── 2 · "ela pode virar obra de arte": o pincel pinta a arte por cima da foto ─────────
const ROWS = 5;
export const S2: React.FC<{ t: number }> = ({ t }) => {
  const a = B1 + 0.08;
  const b = V(5.16) - 0.05;
  const rh = CARD.h / ROWS;
  const prog = lin(t, a, b) * ROWS;
  const row = Math.min(ROWS - 1, Math.floor(prog));
  const rp = Math.min(1, prog - row);
  const ltr = row % 2 === 0;
  const bx = CARD.x + (ltr ? rp : 1 - rp) * CARD.w;
  const by = CARD.y + row * rh + rh / 2;
  const done = t >= b;
  const artH = CARD.w * ART_R;
  const lift = pop(t, V(5.16), 0.45);
  // v7: o pincel pinta a arte sobre a foto do dia e a moldura preta fecha em volta: vira o quadro
  const fw = 22 * io(t, b + 0.12, 0.35);
  const depois = t >= b;
  return (
    <>
      <Checker t={t} tag="02 · obra de arte" />
      <Toolbar t={t} active="brush" />
      <div style={{ position: "absolute", left: CARD.x, top: CARD.y, width: CARD.w, height: CARD.h, transform: `scale(${(1 + lift * 0.06).toFixed(4)})` }}>
        {fw > 0 ? <div style={{ position: "absolute", left: -fw, top: -fw, right: -fw, bottom: -fw, background: INK, boxShadow: "0 30px 60px rgba(0,0,0,0.35)" }} /> : null}
        <div style={{ position: "absolute", inset: 0 }}><OrigImg /></div>
        {Array.from({ length: ROWS }, (_, i) => {
          const p = done ? 1 : i < row ? 1 : i === row ? rp : 0;
          const l2r = i % 2 === 0;
          return (
            <div key={i} style={{ position: "absolute", top: i * rh, height: rh + 1, left: l2r ? 0 : CARD.w * (1 - p), width: CARD.w * p, overflow: "hidden" }}>
              <Img src={staticFile("kadinho/a8.jpg")} style={{ position: "absolute", width: CARD.w, height: artH, left: l2r ? 0 : -CARD.w * (1 - p), top: -i * rh - (artH - CARD.h) / 2 }} />
            </div>
          );
        })}
      </div>
      {t >= B1 ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: CARD.y - 24 - 22 * (depois ? 1 : 0), display: "flex", justifyContent: "center", zIndex: 30, transform: `scale(${(depois ? 1 + (1 - k(t, b, 0.25)) * 0.2 : pop(t, B1 + 0.05, 0.35)).toFixed(3)})` }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 20px 10px", borderRadius: 999, background: depois ? BLUE : INK, color: WHITE, fontFamily: MONO, fontWeight: 600, fontSize: 24, textTransform: "uppercase", boxShadow: "0 10px 24px rgba(0,0,0,0.3)" }}>
            {depois ? "depois · o quadro" : "antes · a foto do dia"}
          </div>
        </div>
      ) : null}
      <Callout t={t} at={b + 0.1} px={410} py={660} lx={560} ly={590} label="várias fotos numa só" sub="composição" />
      <Callout t={t} at={b + 0.4} px={630} py={880} lx={520} ly={1010} label="P&B + uma cor" sub="cor de destaque" />
      {done ? <Ants t={t} x={CARD.x - 16} y={CARD.y - 20} w={CARD.w + 32} h={CARD.h + 40} o={1 - lin(t, b + 0.5, b + 0.8)} /> : null}
      <Col top={1150} gap={10}>
        <Words t={t} font="small" size={46} words={[["ela", V(3.77)], ["pode", V(4.01)], ["virar", V(4.27)]]} />
        <Words t={t} size={112} words={[["obra", V(5.16)], ["de", V(5.39)]]} />
        <Words t={t} size={112} words={[["arte.", V(5.58), BLUE]]} />
      </Col>
      {!done ? <Cursor t={t} x={bx} y={by} kind="brush" /> : <Cursor t={t} x={mix(bx, CARD.x + CARD.w + 50, k(t, b, 0.5))} y={mix(by, CARD.y + CARD.h + 40, k(t, b, 0.5))} />}
    </>
  );
};

// ───────── 3 · logo em caixa de transformação; fotos prediletas viram um quadro ─────────
const FAN = [
  { n: 3, x: -260, r: -9 },
  { n: 12, x: 0, r: 0 },
  { n: 5, x: 260, r: 9 },
];
export const S3: React.FC<{ t: number }> = ({ t }) => {
  const a = B2;
  const out = io(t, a, 0.3);
  const grow = io(t, V(6.68) - 0.05, 0.55);
  const up = io(t, V(7.26) - 0.05, 0.5);
  const lw = up > 0 ? mix(760, 400, up) : mix(320, 760, grow);
  const ly = mix(760, 520, up);
  const lh = lw * (462 / 3035);
  const F = V(8.0) - 0.04;
  const Q = V(9.14) - 0.1;
  const merge = io(t, Q, 0.45);
  const keys: Key[] = [[a, 760, 1160], [V(6.68) - 0.05, 540 + 160 + 20, ly + 25 + 20], [V(6.68) + 0.5, 540 + 380 + 20, ly + 58 + 20], [V(7.26) + 0.6, 900, 1060]];
  const [cx, cy] = pathAt(keys, t);
  return (
    <>
      <Checker t={t} tag="03 · kadocria" />
      <Toolbar t={t} active={t < V(7.26) ? "move" : "marquee"} flash={V(7.26)} />
      {/* a arte da cena anterior sai encolhendo */}
      {out < 1 ? (
        <div style={{ position: "absolute", left: CARD.x, top: CARD.y, width: CARD.w, height: CARD.h, overflow: "hidden", outline: `22px solid ${INK}`, transform: `scale(${(1.06 - out).toFixed(3)}) rotate(${(out * -20).toFixed(1)}deg)`, opacity: 1 - out }}>
          <Img src={staticFile("kadinho/a8.jpg")} style={{ width: CARD.w, height: CARD.w * ART_R, marginTop: -(CARD.w * ART_R - CARD.h) / 2 }} />
        </div>
      ) : null}
      <div style={{ position: "absolute", left: 540 - lw / 2, top: ly - lh / 2, opacity: k(t, V(6.68) - 0.08, 0.15) }}>
        <Logo w={lw} />
      </div>
      {t > V(6.68) - 0.08 && t < V(7.26) + 0.1 ? <TBox x={540 - lw / 2 - 20} y={ly - lh / 2 - 20} w={lw + 40} h={lh + 40} o={1 - k(t, V(7.26) - 0.1, 0.2)} /> : null}
      {/* três fotos em leque que se juntam e viram um quadro */}
      {t < Q + 0.45
        ? FAN.map((f, i) => {
            const p = pop(t, F + i * 0.12, 0.45);
            return (
              <div key={f.n} style={{ position: "absolute", left: 540 - 150 + f.x * (1 - merge), top: 600 + (1 - p) * 900, transform: `rotate(${(f.r * (1 - merge)).toFixed(2)}deg) scale(${(1 - merge * 0.6).toFixed(3)})`, opacity: 1 - merge }}>
                <PhotoImg n={f.n} w={300} h={380} fy={0.4} style={{ border: `10px solid ${WHITE}` }} />
              </div>
            );
          })
        : null}
      {t >= Q ? (
        <div style={{ position: "absolute", left: 540 - 200, top: 570, transform: `scale(${(0.6 + 0.4 * pop(t, Q + 0.15, 0.5)).toFixed(3)})`, opacity: k(t, Q + 0.15, 0.15) }}>
          <div style={{ padding: 20, background: INK, boxShadow: "0 30px 60px rgba(0,0,0,0.3)" }}>
            <ArtImg n={2} w={360} style={{ boxShadow: "none" }} />
          </div>
        </div>
      ) : null}
      <Col top={1150} gap={8}>
        {t < Q ? (
          <>
            <Words t={t} font="small" size={46} words={[["transforma", V(7.26)], ["suas", V(7.78)]]} />
            <Words t={t} size={112} words={[["fotos", V(8.0)]]} />
            <Words t={t} size={112} words={[["prediletas", V(8.34), BLUE]]} />
          </>
        ) : (
          <>
            <Words t={t} font="small" size={46} words={[["em", Q], ["quadros", V(9.14)]]} />
            <Words t={t} size={100} words={[["esportivos", V(9.5)]]} />
            <Words t={t} size={92} words={[["personalizados", V(10.54), BLUE]]} />
          </>
        )}
      </Col>
      <Cursor t={t} x={cx} y={cy} clicks={[V(6.68) - 0.05, V(7.26)]} />
    </>
  );
};

// ───────── 4 · como funciona, em 3 passos ─────────
const STEPS = ["envio", "arte", "quadro"];
const StepBar: React.FC<{ t: number; cur: number; a: number }> = ({ t, cur, a }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top: 462, display: "flex", justifyContent: "center", alignItems: "center", gap: 18, opacity: k(t, a, 0.3) }}>
    {STEPS.map((s, i) => (
      <div key={s} style={{ display: "flex", alignItems: "center", gap: 18 }}>
        {i > 0 ? <div style={{ width: 50, height: 4, background: i <= cur ? BLUE : "#CFCFCF" }} /> : null}
        <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 22px 12px", borderRadius: 999, background: i === cur ? BLUE : i < cur ? INK : WHITE, color: i <= cur ? WHITE : MUTE, fontFamily: INTER, fontWeight: 700, fontSize: 30, boxShadow: "0 8px 18px rgba(0,0,0,0.12)" }}>
          <span>{`0${i + 1}`}</span>
          <span style={{ fontWeight: 500 }}>{s}</span>
        </div>
      </div>
    ))}
  </div>
);
const Bubble: React.FC<{ t: number; at: number; n: string; x: number; y: number }> = ({ t, at, n, x, y }) => {
  const p = pop(t, at, 0.45);
  return (
    <div style={{ position: "absolute", left: x - 52, top: y - 52, width: 104, height: 104, borderRadius: 30, background: UI, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${p.toFixed(3)})`, boxShadow: "0 16px 30px rgba(0,0,0,0.25)" }}>
      <Icon n={n} s={56} c={WHITE} />
    </div>
  );
};
export const S4: React.FC<{ t: number }> = ({ t }) => {
  const a = B3;
  const s2 = V(13.6) - 0.1;
  const s3 = V(14.78) - 0.1;
  const C = V(16.0) - 0.1; // "em média vinte dias"
  const cur = t < s2 ? 0 : t < s3 ? 1 : 2;
  const tool = t < s2 ? "move" : t < V(14.16) ? (t < V(13.78) ? "lasso" : "brush") : t < s3 ? "text" : "crop";
  let stage: React.ReactNode;
  let words: React.ReactNode;
  if (cur === 0) {
    const fill = lin(t, V(12.58), s2 - 0.1);
    stage = (
      <>
        <div style={{ position: "absolute", left: 180, top: 540, width: 720, height: 560, borderRadius: 36, border: `5px dashed ${BLUE}`, background: "rgba(31,143,255,0.06)", transform: `scale(${(0.9 + 0.1 * k(t, a, 0.4)).toFixed(3)})` }} />
        <div style={{ position: "absolute", left: 0, right: 0, top: 580, display: "flex", justifyContent: "center", opacity: 1 - k(t, V(12.38), 0.2) }}>
          <svg width={110} height={110} viewBox="0 0 24 24" fill="none" stroke={BLUE} strokeWidth={1.8} strokeLinecap="round" strokeLinejoin="round">
            <path d="M12 16V4M7 9l5-5 5 5M4 16v3a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-3" />
          </svg>
        </div>
        {[6, 9, 10].map((n, i) => {
          const p = pop(t, V(12.38) + i * 0.16, 0.45);
          return (
            <div key={n} style={{ position: "absolute", left: 230 + i * 215, top: 600 + (1 - p) * 900, transform: `rotate(${((i - 1) * 4).toFixed(1)}deg)` }}>
              <PhotoImg n={n} w={190} h={250} fy={0.4} style={{ border: `8px solid ${WHITE}` }} />
            </div>
          );
        })}
        <div style={{ position: "absolute", left: 240, top: 940, width: 600, height: 18, borderRadius: 9, background: "#DADADA", overflow: "hidden", opacity: k(t, V(12.58) - 0.1, 0.2) }}>
          <div style={{ width: `${(fill * 100).toFixed(1)}%`, height: "100%", background: BLUE }} />
        </div>
        <div style={{ position: "absolute", left: 0, right: 0, top: 990, textAlign: "center", fontFamily: INTER, fontWeight: 600, fontSize: 34, color: MUTE, opacity: k(t, V(12.58), 0.2) }}>{fill < 1 ? `enviando ${Math.round(fill * 3)} de 3 fotos` : "3 fotos enviadas ✓"}</div>
      </>
    );
    words = (
      <>
        <Words t={t} size={112} words={[["você", V(12.14)], ["manda", V(12.38)]]} />
        <Words t={t} size={112} words={[["as", V(12.58)], ["fotos", V(12.8), BLUE]]} />
      </>
    );
  } else {
    // passo 2: a arte se monta; passo 3: vira quadro e o prazo aparece
    const reveal = lin(t, s2 + 0.1, s3 - 0.1);
    const framed = io(t, s3, 0.4);
    const side = io(t, C, 0.45);
    const w = mix(400, 300, side);
    const left = mix(540 - 200, 150, side);
    const top = mix(570, 610, side);
    const h = w * ART_R;
    const fw = 18 * framed;
    stage = (
      <>
        <div style={{ position: "absolute", left: left - fw, top: top - fw, padding: fw, background: INK, boxShadow: `0 ${30 * framed}px 60px rgba(0,0,0,${(0.3 * framed).toFixed(2)})` }}>
          <div style={{ width: w, height: h, position: "relative", background: "rgba(255,255,255,0.5)", outline: framed < 0.5 ? `2px dashed ${MUTE}` : undefined }}>
            <div style={{ position: "absolute", left: 0, top: 0, width: w, height: h * (framed > 0 ? 1 : reveal), overflow: "hidden" }}>
              <Img src={staticFile("kadinho/a14.jpg")} style={{ width: w, height: h, display: "block" }} />
            </div>
          </div>
        </div>
        {cur === 1 ? <Ants t={t} x={left + 40} y={top + h * reveal - 40} w={w - 80} h={70} r={35} o={reveal < 1 ? 1 : 0} /> : null}
        {cur === 1 ? (
          <>
            <Bubble t={t} at={V(13.6)} n="lasso" x={220} y={640} />
            <Bubble t={t} at={V(13.78)} n="brush" x={860} y={660} />
            <Bubble t={t} at={V(14.06)} n="eyedrop" x={210} y={970} />
            <Bubble t={t} at={V(14.16)} n="text" x={870} y={990} />
          </>
        ) : null}
        {cur === 2 ? (
          <div style={{ position: "absolute", left: left + w - 40 + fw, top: top - 40 - fw, width: 96, height: 96, borderRadius: 48, background: BLUE, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${pop(t, V(15.52), 0.45).toFixed(3)})`, boxShadow: "0 10px 24px rgba(31,143,255,0.4)" }}>
            <svg width={56} height={56} viewBox="0 0 24 24" fill="none" stroke={WHITE} strokeWidth={3} strokeLinecap="round" strokeLinejoin="round"><path d="M5 12l5 5 9-10" /></svg>
          </div>
        ) : null}
        {side > 0 ? (
          <div style={{ position: "absolute", left: 560, top: 650, width: 340, height: 340, borderRadius: 34, background: WHITE, boxShadow: "0 24px 50px rgba(0,0,0,0.2)", overflow: "hidden", transform: `scale(${pop(t, C + 0.1, 0.45).toFixed(3)})` }}>
            <div style={{ height: 86, background: BLUE, display: "flex", alignItems: "center", justifyContent: "center", gap: 70 }}>
              <div style={{ width: 16, height: 40, borderRadius: 8, background: WHITE, marginTop: -40 }} />
              <div style={{ width: 16, height: 40, borderRadius: 8, background: WHITE, marginTop: -40 }} />
            </div>
            <div style={{ textAlign: "center", fontFamily: SAIRA, fontWeight: 800, fontSize: 170, color: INK, lineHeight: 1.25 }}>{Math.max(1, Math.round(lin(t, C + 0.15, V(16.92)) * 20))}</div>
            <div style={{ textAlign: "center", fontFamily: INTER, fontWeight: 600, fontSize: 32, color: MUTE, marginTop: -16 }}>dias</div>
          </div>
        ) : null}
      </>
    );
    words =
      cur === 1 ? (
        <>
          <Words t={t} size={112} words={[["ele", V(13.6)], ["cria", V(13.78)]]} />
          <Words t={t} size={112} words={[["a", V(14.06)], ["arte", V(14.16), BLUE]]} />
        </>
      ) : t < C ? (
        <>
          <Words t={t} font="small" size={46} words={[["e", V(14.78)], ["o", V(14.86)], ["quadro", V(14.94)], ["fica", V(15.22)]]} />
          <Words t={t} size={112} words={[["pronto", V(15.52), BLUE]]} />
        </>
      ) : (
        <>
          <Words t={t} font="small" size={46} words={[["em", C + 0.1], ["média", V(16.14)]]} />
          <Words t={t} size={112} words={[["20", V(16.92), BLUE], ["dias", V(17.28)]]} />
        </>
      );
  }
  const keys: Key[] = [[a, 900, 1100], [s2 - 0.1, 860, 1080], [s2, toolX("lasso"), TOOL_Y], [V(13.78), toolX("brush"), TOOL_Y], [V(14.16), toolX("text"), TOOL_Y], [s3, 760, 1000], [C, 860, 1060]];
  const [cx, cy] = pathAt(keys, t);
  return (
    <>
      <Checker t={t} tag="04 · como funciona" />
      <Toolbar t={t} active={tool} flash={t < s3 ? (t < V(13.78) ? s2 : t < V(14.16) ? V(13.78) : V(14.16)) : s3} />
      <StepBar t={t} cur={cur} a={a} />
      {stage}
      <Col top={1170} gap={10}>{words}</Col>
      <Cursor t={t} x={cx} y={cy} clicks={[s2, V(13.78), V(14.16)]} />
    </>
  );
};

// ───────── 5 · "cada arte conta uma história": a ferramenta de texto digita a frase ─────────
export const S5: React.FC<{ t: number }> = ({ t }) => {
  const a = B4;
  const full = "UMA HISTÓRIA.";
  const t0 = V(19.96) - 0.04;
  const n = Math.floor(lin(t, t0, t0 + 0.6) * full.length + 0.001);
  const typed = full.slice(0, n);
  const z = 1 + lin(t, a, B5) * 0.05;
  return (
    <>
      <Checker t={t} tag="05 · a história" />
      <Toolbar t={t} active="text" flash={a + 0.1} />
      <div style={{ position: "absolute", left: 540 - 235, top: 450, transform: `scale(${z.toFixed(4)}) rotate(${mix(-3, 1.5, lin(t, a, B5)).toFixed(2)}deg)`, transformOrigin: "50% 40%" }}>
        <ArtImg n={10} w={470} />
      </div>
      <Col top={1170} gap={18}>
        <Words t={t} font="small" size={46} words={[["porque", V(18.4)], ["cada", V(18.66)], ["arte", V(18.98)], ["conta", V(19.68)]]} />
        <div style={{ position: "relative", padding: "10px 24px", border: t >= t0 - 0.2 ? `2px dashed ${MUTE}` : "2px solid transparent", minWidth: 780, height: 118, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <div style={{ fontFamily: SAIRA, fontWeight: 800, fontSize: 96, lineHeight: 1, color: fg(t), textTransform: "uppercase", whiteSpace: "nowrap", letterSpacing: "-0.01em" }}>
            <span>{typed.slice(0, 4)}</span>
            <span style={{ color: BLUE }}>{typed.slice(4)}</span>
            <span style={{ display: "inline-block", width: 6, height: 86, marginLeft: 6, verticalAlign: "-6px", background: fg(t), opacity: t >= t0 - 0.2 && (n < full.length || Math.sin(t * 16) > 0) ? 1 : 0 }} />
          </div>
        </div>
      </Col>
    </>
  );
};

